// Presentation/reveal keys historically used only chainId + logical day.
// Testnet redeploys restart day numbering on the same chain, so an old run's
// "already revealed" flags can otherwise suppress a brand-new jackpot/flip.

import { CHAIN, CONTRACTS } from './chain-config.js';

const PRESENTATION_PREFIXES = Object.freeze([
  `flip_day_${CHAIN.id}_`,
  `spun_day_${CHAIN.id}_`,
  `jackpot_complete_day_${CHAIN.id}_`,
  `jackpot_bonus_pending_day_${CHAIN.id}_`,
  `flip_settlement_${CHAIN.id}_`,
  `flip_reward_reveal_gate_${CHAIN.id}_`,
  // Keep v2 so a long-idle browser still sheds the pre-rename keys, and carry v3:
  // coinflip.js renamed this prefix (the auto-rebuy carry fix) without updating
  // this list, which silently orphaned the sweep for resolved stakes — every run
  // since then inherited the previous run's per-day stake numbers.
  `coinflip_resolved_stake_v2:${CHAIN.id}:`,
  `coinflip_resolved_stake_v3:${CHAIN.id}:`,
  // last-day-jackpot's per-day summary cache — day-scoped like the reveal gates
  // above, so an old run's day N summary otherwise renders on the new run's day N.
  `day_summary_${CHAIN.id}_`,
  `pari-results-seen:${CHAIN.id}:`,
  `jackpot-resolution-seen:${CHAIN.id}:`,
  // replay-panel: a purchase day's craps battle this viewer has opened.
  `craps-battle-seen:${CHAIN.id}:`,
]);

// Keys already scoped by a per-run CONTRACT address self-namespace and are
// deliberately NOT listed — `degenerus:bingo:{chain}:{GAME}` (bingo-watch) and
// `coinflip_biggest_record_v1:{chain}:{COINFLIP}`. A redeploy changes the address,
// so the old run's entries become unreachable rather than stale.
//
// When adding a presentation key: scope it by a contract address, OR add its
// prefix here. A key scoped only by chainId + day WILL collide across runs,
// because a testnet redeploy restarts day numbering on the same chain.

export function resetPresentationStateForDeployment(storage = globalThis.localStorage) {
  if (!storage) return false;
  // `_v2` bump: the marker is what makes this run ONCE per deployment, so widening
  // PRESENTATION_PREFIXES does nothing for a browser that already swept this
  // deployment under the narrower list — it would carry the missed keys until the
  // NEXT redeploy. Renaming the marker reads as unset once and re-sweeps with the
  // corrected list. Bump it again whenever a prefix is ADDED mid-run; the cost is
  // one extra reveal replay, which the network state immediately re-derives.
  const markerKey = `presentation_deploy_v2_${CHAIN.id}`;
  const deployment = String(CHAIN.deployBlock || 0);
  try {
    if (storage.getItem(markerKey) === deployment) return false;
    const doomed = [];
    for (let index = 0; index < Number(storage.length || 0); index += 1) {
      const key = storage.key(index);
      if (key && PRESENTATION_PREFIXES.some((prefix) => key.startsWith(prefix))) {
        doomed.push(key);
      }
    }
    for (const key of doomed) storage.removeItem(key);
    storage.setItem(markerKey, deployment);
    return true;
  } catch (_e) {
    // Private browsing can deny enumeration. Network state still refreshes;
    // only the one-time stale-presentation cleanup degrades.
    return false;
  }
}

// Per-run caches are scoped by deploy block or Craps contract, so a redeploy makes the old ones
// unreachable, but nothing ever deleted them. One returning Brave profile carried ~20 dead runs:
// 4.48M of Chromium's ~5M-character localStorage quota, almost all old Craps log windows
// (260-610K each). Near the quota every write fails silently, including the reveal markers the
// jackpot handoff depends on; that profile stuck on JACKPOT PROCESSING where a private window
// worked. Runs every load (key names only) so a finished run's data goes as soon as the site
// moves to the next deployment.
export function pruneOtherDeployments(storage = globalThis.localStorage) {
  if (!storage) return 0;
  const chain = String(CHAIN.id);
  const block = String(Number(CHAIN.deployBlock) || 0);
  const craps = String(CONTRACTS?.CRAPS || '').toLowerCase();
  const stale = (key) => {
    let m;
    if ((m = key.match(/^craps-window-(?:api|logs):v1:(\d+):(0x[0-9a-f]+)(?::(\d+))?$/i))) {
      return m[1] === chain && Boolean(craps) && (m[2].toLowerCase() !== craps || m[3] !== block);
    }
    if ((m = key.match(/^pack_(?:pending|revealed|jackpot_awards)_(\d+)_(\d+)(?:_|$)/))) {
      return m[1] === chain && m[2] !== block;
    }
    if ((m = key.match(/^craps-resolution-seen:v2:(\d+):(0x[0-9a-f]+):/i))) {
      return m[1] === chain && Boolean(craps) && m[2].toLowerCase() !== craps;
    }
    if ((m = key.match(/^craps-resolution-seen:(\d+):(\d+):/))) return m[1] === chain && m[2] !== block;
    if ((m = key.match(/^degenerus:wwxrp-draw-days:v1:(\d+):(\d+):/))) return m[1] === chain && m[2] !== block;
    // Retired formats: nothing writes these any more, so every copy is left over from old runs.
    if (key.startsWith(`coinflip_resolved_stake_v1:${chain}:`)) return true;
    return key === `presentation_deploy_${chain}`;
  };
  try {
    const doomed = [];
    for (let index = 0; index < Number(storage.length || 0); index += 1) {
      const key = storage.key(index);
      if (key && stale(key)) doomed.push(key);
    }
    for (const key of doomed) storage.removeItem(key);
    return doomed.length;
  } catch (_e) {
    return 0;
  }
}
